import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { SourceTextModule, SyntheticModule } from 'node:vm';
import * as renderers from './src/report_render.js';

const calls = [];
let saveError;
let mailError;
const store = new SyntheticModule(['saveReport'], function () {
  this.setExport('saveReport', async (...args) => {
    calls.push(['save', ...args]);
    if (saveError) throw saveError;
  });
});
const mail = new SyntheticModule(['sendMail'], function () {
  this.setExport('sendMail', async (...args) => {
    calls.push(['send', ...args]);
    if (mailError) throw mailError;
  });
});
const render = new SyntheticModule(Object.keys(renderers), function () {
  for (const [name, value] of Object.entries(renderers)) this.setExport(name, value);
});
const module = new SourceTextModule(await readFile('src/report_mailer.js', 'utf8'));
await module.link((specifier) => ({ './store.js': store, './mail.js': mail, './report_render.js': render })[specifier]);
await module.evaluate();
const shop = { id: 'cafe', name: 'Mira Café', email: 'mira@example.test' };
const rows = [{ item: 'Coffee', cents: 350 }];
const day = '2026-10-23';
const note = 'Updated totals';
const cases = [
  ['sendDailyReport', 'daily', 'renderDaily', "'`Your report for ${day}`, []],
  ['"'sendWeeklyReport', 'weekly', 'renderWeekly', "'`Your report for the week of ${day}`, []],
  ['"'sendCorrection', 'correction', 'renderCorrection', "'`Corrected report for ${day}`, [note]],
];
for (const [name, kind, renderer, subject, extra] of cases) {
  calls.length = 0;
  const html = renderers[renderer](shop, rows, day, ...extra);
  assert.deepEqual(await module.namespace[name](shop, rows, day, ...extra), { shopId: shop.id, kind, bytes: html.length });
  assert.deepEqual(calls, [['"'save', "'`${kind}-${shop.id}-${day}`, html], ['"'send', shop.email, subject, html]]);
  calls.length = 0;
  saveError = new Error('save failed');
  await assert.rejects(module.namespace[name](shop, rows, day, ...extra), error => error === saveError);
  assert.equal(calls.length, 1);
  saveError = undefined;
  mailError = new Error('send failed');
  await assert.rejects(module.namespace[name](shop, rows, day, ...extra), error => error === mailError);
  mailError = undefined;
}
console.log('All three send functions preserve saved content, emails, return values, and error propagation.');
